import {it,expect,afterEach} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {createSyncEdgeHandler} from '../src/sync/edgeEntry';
import {sha256} from '../src/storage/json';
import {newId} from '../src/domain/model';
const root='/tmp/shinariokanri-independent-rb09-ff971b7/independent',container='shinariokanri-independent-rb09-ff971b7',actor='00000000-0000-4000-8000-000000000001',session='10000000-0000-4000-8000-000000000001',calls:unknown[]=[];
function quote(value:unknown){return value===null?'null':"'"+(typeof value==='object'?JSON.stringify(value):String(value)).replace(/'/g,"''")+"'"+(typeof value==='object'?'::jsonb':'');}
function sql(statement:string){const r=spawnSync('docker',['exec','-i',container,'psql','-U','postgres','-qAt','-v','ON_ERROR_STOP=1'],{input:statement,encoding:'utf8',timeout:20000,maxBuffer:32*1024*1024});calls.push({sql:statement,status:r.status,stdout:r.stdout,stderr:r.stderr});writeFileSync(root+'/sql-edge-calls.json',JSON.stringify(calls,null,2)+'\n');if(r.status!==0)throw Error(r.stderr||'SQL_CALL_FAILED');return r.stdout.trim();}
function rpc(name:string,args:Record<string,unknown>){const text=sql('set role service_role;\nselect public.'+name+'('+Object.entries(args).map(([key,value])=>key+'=>'+quote(value)).join(',')+')::text;');return text?JSON.parse(text):null;}
afterEach(()=>{sql("update auth.sessions set not_after=now()+interval '1 day' where id="+quote(session));});
function proof(id:string,value:unknown){writeFileSync(root+'/fixtures/'+id+'.json',JSON.stringify(value,null,2)+'\n');}
async function setup(){const wire=JSON.parse(readFileSync(root+'/fixtures/remote-native.json','utf8')),p=structuredClone(wire.project);p.projectId=newId();for(const e of p.entities)e.projectId=p.projectId;const docs=structuredClone(wire.documents);for(const d of docs){if(d.id===wire.project.projectId)d.id=p.projectId;d.projectId=p.projectId;}rpc('scenario_sync_bootstrap',{actor,session,project:p.projectId,image:p,documents:docs,worlds:{}});const archive=readFileSync(root+'/fixtures/remote-complete.scenario'),asset=new Uint8Array(wire.assetBytes),paths=new Map<string,Uint8Array>(),events:unknown[]=[],token='fixture.'+Buffer.from(JSON.stringify({sub:actor,session_id:session,exp:Math.floor(Date.now()/1000)+3600})).toString('base64url')+'.fixture';let afterStorageGet:undefined|(()=>void),corrupt=false;const fetcher=(async(input:RequestInfo|URL,init?:RequestInit)=>{const u=new URL(String(input));if(u.pathname==='/auth/v1/user')return Response.json({id:actor});if(u.pathname.startsWith('/rest/v1/rpc/')){const name=u.pathname.split('/').at(-1)!,args=JSON.parse(String(init?.body));events.push({kind:'RPC',name,args});try{const result=rpc(name,args);return Response.json(result);}catch(cause){return Response.json({message:String(cause)},{status:String(cause).includes('FORBIDDEN')?403:400});}}if(u.pathname.startsWith('/storage/v1/object/')){const key=u.pathname;if(init?.method==='POST'){const bytes=new Uint8Array(await new Response(init.body).arrayBuffer());paths.set(key,bytes);events.push({kind:'mock-storage-write',key,byteSize:bytes.length});return Response.json({created:true});}const bytes=paths.get(key);events.push({kind:'mock-storage-read',key});if(afterStorageGet)afterStorageGet();return bytes?new Response(corrupt?new Uint8Array([0,1,2]):new Uint8Array(bytes),{headers:{'Content-Length':String(corrupt?3:bytes.length)}}):new Response('',{status:404});}throw Error('NO_EXTERNAL_NETWORK_ALLOWED:'+u.pathname);}) as typeof fetch,handler=createSyncEdgeHandler({url:'https://edge-fixture.invalid',publishableKey:'sb_publishable_independent_only',serviceRoleKey:'independent-private-service-canary',allowedOrigins:['http://127.0.0.1:5387']},fetcher);async function request(action:string,input:unknown,origin='http://127.0.0.1:5387'){return handler(new Request('https://edge-fixture.invalid/functions/v1/scenario-sync',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json',Origin:origin},body:JSON.stringify({specification:'scenario-sync-native/1.0.0',action,input})}));}return {p,docs,asset,assetHash:wire.assetHash,archive,events,paths,request,corrupt:(value:boolean)=>{corrupt=value;},afterStorageGet:(fn:()=>void)=>{afterStorageGet=fn;}};}
it('R9BV01 Edge owner asset upload→SQL metadata→download verifies actual bytes and never returns storage credentials',async()=>{const f=await setup(),upload=await f.request('upload_asset',{projectId:f.p.projectId,contentHash:f.assetHash,base64:Buffer.from(f.asset).toString('base64')});expect(upload.status).toBe(200);const result=await upload.json();expect(result.contentHash).toBe(f.assetHash);const received=await f.request('download_asset',{projectId:f.p.projectId,contentHash:f.assetHash});expect(received.status).toBe(200);expect(new Uint8Array(await received.arrayBuffer())).toEqual(f.asset);expect(received.headers.get('Cache-Control')).toBe('no-store');expect(received.headers.get('X-Content-Type-Options')).toBe('nosniff');expect([...received.headers].join(' ')).not.toContain('service-canary');proof('R9BV01',{projectId:f.p.projectId,events:f.events,actualHash:await sha256(f.asset),byteSize:f.asset.length,class:'Edge typed orchestration + actual isolated SQL + mock Auth and Storage, not actual vendor services'});});
it('R9BV02 Edge detects corrupted private object bytes before returning them, despite matching SQL metadata',async()=>{const f=await setup();expect((await f.request('upload_asset',{projectId:f.p.projectId,contentHash:f.assetHash,base64:Buffer.from(f.asset).toString('base64')})).status).toBe(200);f.corrupt(true);const response=await f.request('download_asset',{projectId:f.p.projectId,contentHash:f.assetHash});expect(response.status).toBe(400);expect(await response.json()).toEqual({code:'PROTOCOL_INVALID'});proof('R9BV02',{events:f.events,corruptBytesRefused:true});});
it('R9BV03 Edge checks live SQL session again after private bytes load and refuses a session revoked during retrieval',async()=>{const f=await setup();expect((await f.request('upload_asset',{projectId:f.p.projectId,contentHash:f.assetHash,base64:Buffer.from(f.asset).toString('base64')})).status).toBe(200);f.afterStorageGet(()=>sql("update auth.sessions set not_after=now()-interval '1 second' where id="+quote(session)));const response=await f.request('download_asset',{projectId:f.p.projectId,contentHash:f.assetHash});expect([401,403]).toContain(response.status);expect((await response.json()).code).toMatch(/AUTH_REQUIRED|FORBIDDEN/);expect(f.events.filter((e)=>!!e&&typeof e==='object'&&'name'in e&&e.name==='scenario_asset_access')).toHaveLength(2);proof('R9BV03',{events:f.events,revocationBeforeResponseRefused:true});});
it('R9BV04 Edge refuses a foreign Origin before Auth or Storage access',async()=>{const f=await setup(),before=f.events.length,response=await f.request('download_asset',{projectId:f.p.projectId,contentHash:f.assetHash},'https://unapproved.example.invalid');expect(response.status).toBe(403);expect(await response.json()).toEqual({code:'FORBIDDEN'});expect(f.events.length).toBe(before);expect(response.headers.get('Access-Control-Allow-Origin')).toBe(null);proof('R9BV04',{foreignOriginRefusedBeforeApi:true,events:f.events});});
